sources.custom:
function patchedCustom(...args) {
      const info = entryFromCall(spec, args, source);
      if (!info) return call.apply(this, args);
      const factory = args[0];
      args[0] = (...factoryArgs) => {
        const bind = (component) => {
          if (component && typeof component === "object") sink.bind(component, info);
          return component;
        };
        const produced = factory(...factoryArgs);
        if (produced && typeof produced.then === "function") {
          return produced.then(bind);
        }
        return bind(produced);
      };
      return call.apply(this, args);
    }

